def count_shared_unique_words(text1: str, text2: str) -> int:
    """Count the number of unique words that appear in both texts.

    Words are compared case-insensitively and split on whitespace.

    Examples:
        count_shared_unique_words("apple banana apple", "Banana cherry") == 1
        count_shared_unique_words("a b c", "d e f") == 0
    """
    words1 = {word.lower() for word in text1.split()}
    words2 = {word.lower() for word in text2.split()}
    return len(words1 & words2)
