def count_reachable_within_k_steps(graph: dict, start: int, k: int) -> int:
    """
    Count how many distinct nodes are reachable from `start` using at most `k` edges,
    where the graph is an undirected simple graph represented as an adjacency dict.
    Nodes not present as keys have no outgoing edges (but may appear in neighbor lists).

    Examples:
        graph = {0: [1, 2], 1: [0, 3], 2: [0], 3: [1]}
        count_reachable_within_k_steps(graph, 0, 1) == 3   # nodes 0, 1, 2
        count_reachable_within_k_steps(graph, 0, 2) == 4   # nodes 0, 1, 2, 3
    """
    if k < 0:
        return 0

    visited = {start}
    frontier = {start}

    for _ in range(k):
        next_frontier = set()
        for node in frontier:
            for neighbor in graph.get(node, []):
                if neighbor not in visited:
                    visited.add(neighbor)
                    next_frontier.add(neighbor)
        if not next_frontier:
            break
        frontier = next_frontier

    return len(visited)
```

