def parse_flags(text: str) -> dict:
    """Parse a string of space-separated flags into a dict.

    Each token is either a bare flag like '--verbose' (value True)
    or a key=value pair like 'name=alice' (value is the string after '=').
    Tokens are separated by whitespace; empty input yields an empty dict.

    >>> parse_flags('--verbose name=alice')
    {'--verbose': True, 'name': 'alice'}
    >>> parse_flags('a=1 b=2 c')
    {'a': '1', 'b': '2', 'c': True}
    """
    result = {}
    for token in text.split():
        if '=' in token:
            key, value = token.split('=', 1)
            result[key] = value
        else:
            result[token] = True
    return result
```

